    def send_say(self, message: str) -> Result:
        """``async sendSay(message: string): Promise<ActionResult>`` (sdk.sendSay)
        
        Send a single chat message. The server caps public chat at {@link maxMessageLength} chars (400 on rs-sdk servers) and runs a word filter; `result.data` reports `{ sent, truncated, filtered, finalText }` so you know if your message was clipped or censored. For longer text that shouldn't be silently truncated, use {@link say}.
        """
        return self._call("sdk.sendSay", message)  # type: ignore[no-any-return]

    def say(self, text: str, opts: Any = None) -> list[Result]:
        """``async say(text: string, opts: { maxLen?: number; delayTicks?: number } = {}): Promise<ActionResult[]>`` (sdk.say)
        
        Send a message of any length, auto-split into chunks on word boundaries and sent in order (so a multi-sentence plan isn't lost to the chat-length cap). Waits a tick between chunks so they don't collide. Returns one ActionResult per chunk.
        """
        return self._call("sdk.say", text, opts)  # type: ignore[no-any-return]

    def send_private_message(self, target_name: str, message: str) -> Result:
        """``async sendPrivateMessage(targetName: string, message: string): Promise<ActionResult>`` (sdk.sendPrivateMessage)
        
        Send a single private message to another player by name. Delivered if the target is online anywhere in the world - no friends-list setup needed. It arrives in their chat as type 3 ("From <you>"), and echoes locally as type 6 ("To <name>"). Same length cap and word filter as {@link sendSay}; the server accepts at most one social packet (say or PM) per tick, so don't fire this back-to-back with public chat in the same tick. For longer text, use {@link dm}.
        """
        return self._call("sdk.sendPrivateMessage", target_name, message)  # type: ignore[no-any-return]

    def dm(self, target_name: str, text: str, opts: Any = None) -> list[Result]:
        """``async dm(targetName: string, text: string, opts: { maxLen?: number; delayTicks?: number } = {}): Promise<ActionResult[]>`` (sdk.dm)
        
        Send a private message of any length, auto-split into chunks like {@link say}. Returns one ActionResult per chunk.
        """
        return self._call("sdk.dm", target_name, text, opts)  # type: ignore[no-any-return]

